import raw from './voices.json';
import { getAssetUrl } from '../utils/osDetect';

// Generated by scripts/build-voices.mjs from the app's own model files —
// names and avatars match the voice changer exactly. Do not edit by hand.
export interface Voice {
  id: string;
  model: 'jvs' | 'official_1' | 'old_tts';
  name: string;
  code?: string;
  gender?: 'female' | 'male';
  avatar: string;
}

export const VOICES: Voice[] = (raw as Voice[]).map((v) => ({ ...v, avatar: getAssetUrl(v.avatar) }));

export const voiceTag = (v: Voice) =>
  v.code ?? (v.model === 'official_1' ? 'OFFICIAL' : 'CLASSIC TTS');
